src/DavinciDKGAdapter.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

import {IDKGManager} from "./interfaces/dkg/IDKGManager.sol";
import {IDKGAppManager} from "./interfaces/dkg/IDKGAppManager.sol";
import {DKGTypes} from "./interfaces/dkg/DKGTypes.sol";
import {DAVINCITypes} from "./libraries/DAVINCITypes.sol";
import {BjjFormLib} from "./libraries/BjjFormLib.sol";

/**
 * @title DavinciDKGAdapter
 * @notice The registry's seam to the davinci-dkg contracts: it registers one DKG
 *         application per DKG-mode process, is its sole ciphertext submitter, converts
 *         BabyJubJub points between the circomlib form (DAVINCI) and the reduced form
 *         (DKG), and reads combined plaintexts back. Created by the ProcessRegistry
 *         constructor, so `registry` is fixed to its creator.
 */
contract DavinciDKGAdapter {
    /// @notice The ProcessRegistry that created this adapter; the only allowed caller
    ///         of the state-changing functions.
    address public immutable registry;
    /// @notice The davinci-dkg manager (epochs, pool keys, ciphertexts, combines).
    IDKGManager public immutable manager;
    /// @notice The davinci-dkg application manager (registration, organizer reveal).
    IDKGAppManager public immutable appManager;

    /// @dev MAX_K in the DKG: pool keys per epoch.
    uint8 private constant MAX_POOL_KEYS = 16;
    /// @dev How many epochs registrationEpoch scans backwards from the newest.
    uint64 private constant EPOCH_SCAN = 8;

    error NotRegistry();
    error NoLiveEpoch();
    error NonContiguousIndex();

    modifier onlyRegistry() {
        if (msg.sender != registry) revert NotRegistry();
        _;
    }

    constructor(address dkgManager) {
        registry = msg.sender;
        manager = IDKGManager(dkgManager);
        appManager = IDKGAppManager(IDKGManager(dkgManager).appManager());
    }

    /// @notice The DKG application id of a process: keccak(chainid, registry, pid) mod Q,
    ///         never 0. Deterministic and collision-free across registries.
    function aidFor(bytes31 processId) public view returns (bytes32) {
        uint256 a = uint256(keccak256(abi.encode(block.chainid, registry, processId))) % BjjFormLib.Q;
        if (a == 0) a = 1;
        return bytes32(a);
    }

    /// @notice The newest Live epoch with a free pool key, scanning backwards at most
    ///         EPOCH_SCAN epochs from the manager's newest. Reverts NoLiveEpoch when
    ///         none qualifies.
    function registrationEpoch() public view returns (bytes12) {
        uint64 nonce = manager.epochNonce();
        uint96 prefix = uint96(manager.EPOCH_PREFIX()) << 64;
        for (uint64 i = 0; i < EPOCH_SCAN && nonce > i; ++i) {
            bytes12 eid = bytes12(prefix | uint96(nonce - i));
            uint8 next = manager.getPoolStatus(eid);
            if (next >= MAX_POOL_KEYS) continue; // pool spent
            // getPoolKey reverts InvalidPhase unless the epoch is Live.
            try manager.getPoolKey(eid, next) returns (uint256, uint256) {
                return eid;
            } catch {}
        }
        revert NoLiveEpoch();
    }

    /// @notice Registers the DKG application of `processId` and returns its epoch, aid
    ///         and encryption key `PK_aid` converted to circomlib form. LOCKED mode uses
    ///         the caller-chosen epoch (the Schnorr PoP binds it); AUTOMATIC picks
    ///         registrationEpoch().
    function register(bytes31 processId, DAVINCITypes.DKGParams calldata dkg)
        external
        onlyRegistry
        returns (bytes12 eid, bytes32 aid, uint256 teX, uint256 teY)
    {
        aid = aidFor(processId);
        bool locked = dkg.mode == DAVINCITypes.KeyMode.DKG_LOCKED;
        eid = locked ? dkg.epochId : registrationEpoch();

        address[] memory submitters = new address[](1);
        submitters[0] = address(this);
        DKGTypes.AppPolicy memory policy = DKGTypes.AppPolicy({
            mode: locked ? DKGTypes.AppMode.OrganizerLocked : DKGTypes.AppMode.Automatic,
            openSubmission: false,
            submitters: submitters,
            maxCiphertexts: 16,
            notBeforeBlock: 0,
            notAfterBlock: 0,
            decryptNotBefore: 0,
            decryptNotAfter: 0
        });
        appManager.registerApplication(eid, aid, policy, dkg.orgPKx, dkg.orgPKy, dkg.popAx, dkg.popAy, dkg.popZ);

        (uint256 rx, uint256 ry) = appManager.getApplicationKey(eid, aid);
        teX = BjjFormLib.toTE(rx);
        teY = ry;
    }

    /// @notice Submits ElGamal ciphertexts (circomlib coordinates, [c1x, c1y, c2x, c2y]
    ///         each) to the DKG, converting to the reduced form. Returns the on-chain
    ///         index of the first one and requires the rest to follow contiguously:
    ///         finalize reads [first, first + count), so a gap would silently map the
    ///         wrong plaintexts to fields.
    function submit(bytes12 eid, bytes32 aid, uint256[4][] calldata ciphertextsTE)
        external
        onlyRegistry
        returns (uint16 firstIndex)
    {
        for (uint256 i = 0; i < ciphertextsTE.length; ++i) {
            uint256[4] calldata ct = ciphertextsTE[i];
            uint16 idx =
                manager.submitCiphertext(eid, aid, BjjFormLib.toRTE(ct[0]), ct[1], BjjFormLib.toRTE(ct[2]), ct[3]);
            if (i == 0) firstIndex = idx;
            else if (idx != firstIndex + i) revert NonContiguousIndex();
        }
    }

    /// @notice Combined plaintexts of ciphertexts [first, first + count). ready is false
    ///         (and values incomplete) until every one has a completed combine.
    function plaintexts(bytes12 eid, bytes32 aid, uint16 first, uint16 count)
        external
        view
        returns (bool ready, uint256[] memory values)
    {
        values = new uint256[](count);
        for (uint16 i = 0; i < count; ++i) {
            DKGTypes.CombinedDecryptionRecord memory rec = manager.getCombinedDecryption(eid, aid, first + i);
            if (!rec.completed) return (false, values);
            values[i] = rec.plaintext;
        }
        ready = true;
    }

    /// @notice Forwards an organizer-secret reveal for a locked application. The DKG
    ///         checks sk·G == PK_org.
    function reveal(bytes12 eid, bytes32 aid, uint256 sk) external onlyRegistry {
        appManager.revealOrganizerSecret(eid, aid, sk);
    }
}

src/interfaces/dkg/DKGTypes.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

/**
 * @title DKGTypes
 * @notice Vendored subset of davinci-dkg `src/libraries/DKGTypes.sol` (commit 2338d8a):
 *         only the types the DAVINCI adapter needs, ABI-identical to upstream.
 */
library DKGTypes {
    struct Point {
        uint256 x;
        uint256 y;
    }

    /// @notice How an application's ciphertexts get decrypted. `OrganizerLocked`
    ///         adds an organizer key (`PK_aid = P_j + PK_org`) that must be
    ///         revealed before the committee can combine; `Automatic` uses the
    ///         pool key alone (`PK_aid = P_j`).
    enum AppMode {
        OrganizerLocked,
        Automatic
    }

    /// @notice Per-application policy, fixed at registration. Submission windows
    ///         are in blocks, decryption windows in unix seconds; 0 = no bound.
    struct AppPolicy {
        AppMode mode;
        bool openSubmission; // anyone may submitCiphertext
        address[] submitters; // allow-list; empty = the registrant only
        uint16 maxCiphertexts; // 0 = unlimited (capped by MAX_CIPHERTEXT_INDEX)
        uint64 notBeforeBlock; // submitCiphertext window (blocks)
        uint64 notAfterBlock;
        uint64 decryptNotBefore; // unix seconds (0 = none)
        uint64 decryptNotAfter; // unix seconds (0 = none)
    }

    /// @notice On-chain application record, as returned by `getApplication`.
    struct Application {
        address creator;
        Point organizerPK; // (0, 1) when Automatic
        uint256 organizerSecret; // 0 while sealed and always when Automatic
        uint8 poolIndex;
        AppPolicy policy;
        uint64 createdAtBlock;
        bool exists;
    }

    struct CombinedDecryptionRecord {
        uint16 ciphertextIndex;
        bool completed;
        uint256 plaintext;
    }
}

src/interfaces/dkg/IDKGAppManager.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

import {DKGTypes} from "./DKGTypes.sol";

/**
 * @title IDKGAppManager
 * @notice Vendored subset of davinci-dkg `src/interfaces/IDKGAppManager.sol`. ABI-identical to upstream.
 */
interface IDKGAppManager {
    error InvalidApplication();
    error ApplicationAlreadyExists();
    error InvalidSchnorrProof();
    error PointNotInSubgroup();
    error InvalidEpoch();
    error InvalidPhase();
    error InvalidOrganizerSecret();
    error InvalidPolicy();
    error AlreadyRevealed();
    error PoolExhausted();

    /// @notice Register an application against a Live epoch and claim the epoch's
    ///         next pool key. In `OrganizerLocked` mode the Schnorr PoP proves
    ///         knowledge of `sk_org` and `PK_aid = P_j + PK_org`; in `Automatic`
    ///         mode the key and Schnorr arguments are ignored and `PK_aid = P_j`.
    ///         Organizer key and PoP are in the DKG's reduced (a = -1) form.
    function registerApplication(
        bytes12 epochId,
        bytes32 aid,
        DKGTypes.AppPolicy calldata policy,
        uint256 pkOrgX,
        uint256 pkOrgY,
        uint256 schnorrAx,
        uint256 schnorrAy,
        uint256 schnorrZ
    ) external;

    /// @notice Publish `sk_org` for an `OrganizerLocked` application, once.
    ///         Permissionless — the contract checks `sk·G == PK_org`.
    function revealOrganizerSecret(bytes12 epochId, bytes32 aid, uint256 organizerSecret) external;

    function getApplication(bytes12 epochId, bytes32 aid) external view returns (DKGTypes.Application memory);

    /// @notice `PK_aid` of a registered application in reduced form: `P_j` for
    ///         `Automatic`, `P_j + PK_org` for `OrganizerLocked`. Reverts
    ///         `InvalidApplication` for an unknown aid.
    function getApplicationKey(bytes12 epochId, bytes32 aid) external view returns (uint256 x, uint256 y);

    /// @notice `PK_org` of a registered application — `(0, 1)` for Automatic ones,
    ///         zero for an unknown aid.
    function getOrganizerPK(bytes12 epochId, bytes32 aid) external view returns (uint256, uint256);
}

src/interfaces/dkg/IDKGManager.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

import {DKGTypes} from "./DKGTypes.sol";

/**
 * @title IDKGManager
 * @notice Vendored subset of davinci-dkg `src/interfaces/IDKGManager.sol` (commit 2338d8a),
 *         plus the public state getters (`appManager`, `epochNonce`, `EPOCH_PREFIX`) the
 *         adapter reads from `DKGManager`. ABI-identical to upstream.
 */
interface IDKGManager {
    error InvalidEpoch();
    error InvalidPhase();
    error InvalidProofInput();
    error InvalidCiphertext();
    error CiphertextAlreadySubmitted();
    error DecryptionLimitReached();
    error PoolExhausted();
    error Unauthorized();

    /// @notice The sibling DKGAppManager (public state variable on DKGManager).
    function appManager() external view returns (address);

    /// @notice Nonce of the newest epoch; epoch ids are
    ///         `bytes12((uint96(EPOCH_PREFIX) << 64) | nonce)` (DKGIdLib.computeEpochId).
    function epochNonce() external view returns (uint64);

    /// @notice The manager's epoch-id prefix (public immutable on DKGManager).
    // solhint-disable-next-line func-name-mixedcase
    function EPOCH_PREFIX() external view returns (uint32);

    /// @notice Submit a ciphertext for threshold decryption under `PK_aid`. The
    ///         index is assigned on chain (1, 2, ... per application) and returned.
    ///         Coordinates must be canonical, on-curve and non-identity.
    function submitCiphertext(bytes12 epochId, bytes32 aid, uint256 c1x, uint256 c1y, uint256 c2x, uint256 c2y)
        external
        returns (uint16 ciphertextIndex);

    function getCombinedDecryption(bytes12 epochId, bytes32 aid, uint16 ciphertextIndex)
        external
        view
        returns (DKGTypes.CombinedDecryptionRecord memory);

    /// @notice The pool key `P_j` of a Live epoch. Reverts `InvalidPhase` before the
    ///         epoch is Live and `InvalidProofInput` for `keyIndex >= MAX_K`.
    function getPoolKey(bytes12 epochId, uint8 keyIndex) external view returns (uint256 x, uint256 y);

    /// @notice `nextIndex` is the pool key the next registration claims
    ///         (`MAX_K` once the pool is spent). Plain mapping read, never reverts.
    function getPoolStatus(bytes12 epochId) external view returns (uint8 nextIndex);

    /// @notice The pool key claimed by `aid`. Reverts `InvalidProofInput` when the
    ///         application never claimed one.
    function getAppPoolIndex(bytes12 epochId, bytes32 aid) external view returns (uint8);
}

